```cpp
#include <cctype>
#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> counts;
    std::string word;
    while (std::cin >> word) {
        for (char& ch : word) {
            ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        }
        // Remove common punctuation from the beginning and end.
        while (!word.empty() && std::ispunct(static_cast<unsigned char>(word.front())))
            word.erase(word.begin());
        while (!word.empty() && std::ispunct(static_cast<unsigned char>(word.back())))
            word.pop_back();
        if (!word.empty()) ++counts[word];
    }

    for (const auto& [token, count] : counts)
        std::cout << token << ": " << count << '\n';
}
