def roman_to_int(s: str) -> int:
    values = {"I":1,"V":5,"X":10,"L":50,"C":100,"D":500,"M":1000}
    s=s.strip().upper()
    if not s: raise ValueError("Roman numeral cannot be empty")
    total=0
    for i,ch in enumerate(s):
        if ch not in values: raise ValueError(f"Invalid character: {ch}")
        cur=values[ch]
        if i+1<len(s) and cur<values[s[i+1]]:
            total-=cur
        else:
            total+=cur
    return total

